import sqlite3
import json
import os
import re
import urllib.parse
import urllib.request
from pathlib import Path
from types import SimpleNamespace
from flask import Flask, render_template, request, abort, session, redirect, url_for, flash
from improved_job_fields import apply_improvements, improve_all_jobs

app = Flask(__name__)
app.secret_key = "smart-placement-secret"
app.config["REMOTE"] = True

BASE_DIR = Path(__file__).resolve().parent
DB_PATH = BASE_DIR / "jobs.db"

# -------------------------
# Database Helpers
# -------------------------

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        CREATE TABLE IF NOT EXISTS sectors (
            key TEXT PRIMARY KEY,
            title TEXT NOT NULL,
            emoji TEXT DEFAULT '📁'
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS departments (
            id TEXT PRIMARY KEY,
            sector_key TEXT NOT NULL,
            key TEXT NOT NULL,
            title TEXT NOT NULL,
            emoji TEXT DEFAULT '📂',
            FOREIGN KEY (sector_key) REFERENCES sectors(key)
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS jobs (
            slug TEXT PRIMARY KEY,
            sector_key TEXT NOT NULL,
            department_key TEXT,
            title TEXT NOT NULL,
            data_json TEXT NOT NULL,
            FOREIGN KEY (sector_key) REFERENCES sectors(key)
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS notification_subscribers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            email TEXT UNIQUE NOT NULL,
            preferred_sector TEXT,
            preferred_degree TEXT,
            keywords TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS live_job_posts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            company TEXT,
            location TEXT,
            source TEXT,
            apply_url TEXT,
            skills TEXT,
            posted_at TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    """)

    existing_live = cur.execute("SELECT COUNT(*) FROM live_job_posts").fetchone()[0]
    if existing_live == 0:
        seed_live_jobs(cur)

    existing = cur.execute("SELECT COUNT(*) FROM sectors").fetchone()[0]
    if existing == 0:
        seed_database(conn)

    conn.commit()
    conn.close()


def seed_live_jobs(cur):
    sample_jobs = [
        ("Python Developer Intern", "Remote Startup", "Remote / India", "Demo API", "https://internshala.com/internships/python-development-internship/", "Python, Flask, SQL, Git", "Latest"),
        ("Data Analyst Fresher", "Analytics Team", "Hyderabad", "Demo API", "https://www.linkedin.com/jobs/", "Excel, SQL, Power BI, Python", "Latest"),
        ("Web Developer Trainee", "IT Services Company", "Bengaluru", "Demo API", "https://www.naukri.com/", "HTML, CSS, JavaScript, Flask", "Latest"),
        ("Cloud Support Associate", "Cloud Operations", "Chennai", "Demo API", "https://www.amazon.jobs/", "Linux, Networking, AWS basics", "Latest"),
        ("Cyber Security Intern", "Security Lab", "Remote", "Demo API", "https://www.linkedin.com/jobs/", "Networking, Python, Security basics", "Latest"),
    ]
    cur.executemany(
        """
        INSERT INTO live_job_posts(title, company, location, source, apply_url, skills, posted_at)
        VALUES (?, ?, ?, ?, ?, ?, ?)
        """,
        sample_jobs
    )


def seed_database(conn):
    cur = conn.cursor()

    for sector_key, sector in SECTORS.items():
        cur.execute(
            "INSERT OR IGNORE INTO sectors(key, title, emoji) VALUES (?, ?, ?)",
            (sector_key, sector.get("title", sector_key), sector.get("emoji", "📁"))
        )

        if "departments" in sector:
            for dept_key, dept in sector.get("departments", {}).items():
                dept_id = f"{sector_key}:{dept_key}"
                cur.execute(
                    "INSERT OR IGNORE INTO departments(id, sector_key, key, title, emoji) VALUES (?, ?, ?, ?, ?)",
                    (dept_id, sector_key, dept_key, dept.get("title", dept_key), dept.get("emoji", "📂"))
                )
                for job in dept.get("jobs", []):
                    insert_job(cur, sector_key, dept_key, job)

        for job in sector.get("jobs", []):
            insert_job(cur, sector_key, None, job)


def insert_job(cur, sector_key, department_key, job):
    data = dict(job)
    data["sector_key"] = sector_key
    if department_key:
        data["department_key"] = department_key

    cur.execute(
        """
        INSERT OR REPLACE INTO jobs(slug, sector_key, department_key, title, data_json)
        VALUES (?, ?, ?, ?, ?)
        """,
        (
            data.get("slug"),
            sector_key,
            department_key,
            data.get("title", data.get("slug", "Untitled Job")),
            json.dumps(data, ensure_ascii=False)
        )
    )


def row_to_job(row):
    job = json.loads(row["data_json"])
    job["slug"] = row["slug"]
    job["title"] = row["title"]
    job["sector_key"] = row["sector_key"]
    if row["department_key"]:
        job["department_key"] = row["department_key"]
    return job


def get_all_jobs():
    conn = get_db()
    rows = conn.execute("SELECT * FROM jobs ORDER BY title COLLATE NOCASE").fetchall()
    conn.close()
    jobs = [row_to_job(row) for row in rows]
    return improve_all_jobs(jobs)


def get_job_by_slug(slug):
    conn = get_db()
    row = conn.execute("SELECT * FROM jobs WHERE slug = ?", (slug,)).fetchone()
    conn.close()
    if not row:
        return None
    return apply_improvements(row_to_job(row))


def find_job_by_slug(sector_key, slug):
    conn = get_db()
    row = conn.execute(
        "SELECT * FROM jobs WHERE sector_key = ? AND slug = ?",
        (sector_key, slug)
    ).fetchone()
    conn.close()
    if not row:
        return None
    return apply_improvements(row_to_job(row))


def get_departments_for_sector(sector_key):
    conn = get_db()
    dept_rows = conn.execute(
        "SELECT * FROM departments WHERE sector_key = ? ORDER BY title COLLATE NOCASE",
        (sector_key,)
    ).fetchall()

    departments = {}
    for dept in dept_rows:
        job_rows = conn.execute(
            "SELECT * FROM jobs WHERE sector_key = ? AND department_key = ? ORDER BY title COLLATE NOCASE",
            (sector_key, dept["key"])
        ).fetchall()
        departments[dept["key"]] = {
            "title": dept["title"],
            "emoji": dept["emoji"],
            "jobs": [apply_improvements(row_to_job(row)) for row in job_rows]
        }

    conn.close()
    return departments


def get_sectors():
    conn = get_db()
    rows = conn.execute("SELECT * FROM sectors ORDER BY rowid").fetchall()
    sectors = {}

    for row in rows:
        sector_key = row["key"]
        sector = {
            "title": row["title"],
            "emoji": row["emoji"],
            "jobs": [],
            "departments": {}
        }

        job_rows = conn.execute(
            "SELECT * FROM jobs WHERE sector_key = ? AND (department_key IS NULL OR department_key = '') ORDER BY title COLLATE NOCASE",
            (sector_key,)
        ).fetchall()
        sector["jobs"] = [apply_improvements(row_to_job(job_row)) for job_row in job_rows]

        dept_rows = conn.execute(
            "SELECT * FROM departments WHERE sector_key = ? ORDER BY title COLLATE NOCASE",
            (sector_key,)
        ).fetchall()
        for dept in dept_rows:
            sub_job_rows = conn.execute(
                "SELECT * FROM jobs WHERE sector_key = ? AND department_key = ? ORDER BY title COLLATE NOCASE",
                (sector_key, dept["key"])
            ).fetchall()
            sector["departments"][dept["key"]] = {
                "title": dept["title"],
                "emoji": dept["emoji"],
                "jobs": [apply_improvements(row_to_job(r)) for r in sub_job_rows]
            }

        sectors[sector_key] = sector

    conn.close()
    return sectors


def get_sector(sector_key):
    return get_sectors().get(sector_key)


def get_portal_stats():
    jobs = get_all_jobs()
    sectors = get_sectors()
    departments_count = sum(len(sector.get("departments", {})) for sector in sectors.values())
    govt_jobs = sum(1 for job in jobs if job.get("sector_key") in ["state", "central"])
    return {
        "jobs_count": len(jobs),
        "sectors_count": len(sectors),
        "departments_count": departments_count,
        "govt_jobs_count": govt_jobs,
    }


def saved_list():
    return session.get("saved_jobs", [])


def compare_list():
    return session.get("compare_jobs", [])


def job_matches_degree(job, degree_text):
    if not degree_text:
        return True
    degree_text = degree_text.lower().strip()
    haystack = (job.get("degree", "") + " " + job.get("title", "") + " " + job.get("skills", "")).lower()
    keywords = {
        "btech": ["b.tech", "btech", "engineering", "be ", "b.e", "diploma"],
        "degree": ["graduate", "any graduate", "degree", "b.sc", "b.com", "b.a"],
        "intermediate": ["intermediate", "12th", "10+2", "pass"],
        "diploma": ["diploma", "iti", "polytechnic"],
        "any": ["any", "graduate", "pass", "diploma", "b.tech", "b.sc"],
    }
    selected = keywords.get(degree_text, [degree_text])
    return any(k in haystack for k in selected)


def job_matches_age(job, age_value):
    if not age_value:
        return True
    try:
        age = int(age_value)
    except ValueError:
        return True
    import re
    ages = [int(x) for x in re.findall(r"\d+", job.get("age", ""))]
    if len(ages) >= 2:
        return min(ages) <= age <= max(ages)
    return True


def require_admin():
    if not session.get("admin_logged_in"):
        return redirect(url_for("admin_login"))
    return None


def build_admin_sector_rows():
    rows = []
    sectors = get_sectors()
    for key, sector in sectors.items():
        jobs = list(sector.get("jobs", []))
        for dept in sector.get("departments", {}).values():
            jobs.extend(dept.get("jobs", []))
        rows.append(SimpleNamespace(
            id=key,
            key=key,
            title=sector.get("title", key),
            emoji=sector.get("emoji", "📁"),
            jobs=jobs
        ))
    return rows


def build_admin_department_rows():
    rows = []
    sectors = get_sectors()
    for sector_key, sector in sectors.items():
        for dept_key, dept in sector.get("departments", {}).items():
            rows.append(SimpleNamespace(
                id=f"{sector_key}:{dept_key}",
                key=dept_key,
                title=dept.get("title", dept_key),
                sector=SimpleNamespace(title=sector.get("title", sector_key))
            ))
    return rows


def build_job_from_form():
    sector_key = request.form.get("sector_id", "").strip()
    department_value = request.form.get("department_id", "").strip()
    department_key = None

    if department_value:
        if ":" in department_value:
            sector_key, department_key = department_value.split(":", 1)
        else:
            department_key = department_value

    slug = request.form.get("slug", "").strip().lower().replace(" ", "-")
    title = request.form.get("title", "").strip()

    pay = {}
    for grade in ["A", "B", "C"]:
        g = grade.lower()
        if request.form.get(f"{g}_basic") or request.form.get(f"{g}_monthly") or request.form.get(f"{g}_annual"):
            pay[grade] = {
                "basic": request.form.get(f"{g}_basic", ""),
                "monthly_total": request.form.get(f"{g}_monthly", ""),
                "annual": request.form.get(f"{g}_annual", "")
            }

        reservation = []
    # Accept both short codes (oc/bc) and common aliases (general/obc)
    reservation_aliases = {
        "oc": ["oc", "general"],
        "bc": ["bc", "obc"],
        "sc": ["sc"],
        "st": ["st"],
        "ews": ["ews"],
    }
    for cat, aliases in reservation_aliases.items():
        value = ""
        for alias in aliases:
            value = request.form.get(f"res_{alias}", "").strip()
            if value:
                break
        if value:
            reservation.append({"category": cat.upper(), "percent": value})

    job = {
        "slug": slug,
        "title": title,
        "sector_key": sector_key,
        "full_description": request.form.get("full_description", ""),
        "age": request.form.get("age", ""),
        "degree": request.form.get("degree", ""),
        "minimum_score": request.form.get("minimum_score", ""),
        "company_name": request.form.get("company_name", ""),
        "vacancies": request.form.get("vacancies", ""),
        "job_location": request.form.get("job_location", ""),
        "employment_type": request.form.get("employment_type", ""),
        "apply_dates": request.form.get("apply_dates", ""),
        "apply_deadline": request.form.get("apply_deadline", ""),
        "exam_dates": request.form.get("exam_dates", ""),
        "apply_link": request.form.get("apply_link", ""),
        "career_page": request.form.get("career_page", ""),
        "company_website": request.form.get("company_website", ""),
        "pay_matrix_link": request.form.get("pay_matrix_link", ""),
        "exam_mode": request.form.get("exam_mode", ""),
        "apply_mode": request.form.get("apply_mode", ""),
        "notes": request.form.get("notes", ""),
        "skills": request.form.get("skills", ""),
        "experience": request.form.get("experience", ""),
        "certifications": request.form.get("certifications", ""),
        "future_demand": request.form.get("future_demand", ""),
        "work_environment": request.form.get("work_environment", ""),
        "job_security": request.form.get("job_security", ""),
        "selection_process": request.form.get("selection_process", ""),
        "promotion_hierarchy": request.form.get("promotion_hierarchy", ""),
        "career_growth": request.form.get("career_growth", ""),
        "roadmap": request.form.get("roadmap", ""),
        "resume_tips": request.form.get("resume_tips", ""),
        "pay": pay,
        "reservation": reservation
    }

    if department_key:
        job["department_key"] = department_key

    return sector_key, department_key, job



def recommend_jobs(profile):
    jobs = get_all_jobs()
    scored = []
    degree = profile.get("degree", "").lower()
    skills = [x.strip().lower() for x in profile.get("skills", "").replace(";", ",").split(",") if x.strip()]
    interest = profile.get("interest", "").lower()
    age = profile.get("age", "")

    for job in jobs:
        score = 0
        reasons = []
        haystack = " ".join([
            job.get("title", ""), job.get("degree", ""), job.get("skills", ""),
            job.get("full_description", ""), job.get("sector_key", "")
        ]).lower()

        if degree and job_matches_degree(job, degree):
            score += 35
            reasons.append("education match")
        if age and job_matches_age(job, age):
            score += 15
            reasons.append("age range suitable")
        matched_skills = [skill for skill in skills if skill and skill in haystack]
        if matched_skills:
            score += min(30, len(matched_skills) * 10)
            reasons.append("skills: " + ", ".join(matched_skills[:3]))
        if interest and interest in haystack:
            score += 20
            reasons.append("interest match")
        if not degree and not skills and not interest:
            score = 10
            reasons.append("general recommendation")

        if score > 0:
            scored.append({"job": job, "score": min(score, 100), "reasons": reasons})

    return sorted(scored, key=lambda x: x["score"], reverse=True)[:12]


def get_notification_subscribers():
    conn = get_db()
    rows = conn.execute("SELECT * FROM notification_subscribers ORDER BY created_at DESC").fetchall()
    conn.close()
    return rows


def get_live_jobs(keyword=""):
    conn = get_db()
    if keyword:
        like = f"%{keyword}%"
        rows = conn.execute(
            """
            SELECT * FROM live_job_posts
            WHERE lower(title) LIKE lower(?) OR lower(company) LIKE lower(?) OR lower(skills) LIKE lower(?) OR lower(location) LIKE lower(?)
            ORDER BY id DESC
            """,
            (like, like, like, like)
        ).fetchall()
    else:
        rows = conn.execute("SELECT * FROM live_job_posts ORDER BY id DESC").fetchall()
    conn.close()
    return rows


def get_analytics_data():
    sectors = get_sectors()
    jobs = get_all_jobs()
    sector_counts = []
    for key, sector in sectors.items():
        count = len(sector.get("jobs", [])) + sum(len(d.get("jobs", [])) for d in sector.get("departments", {}).values())
        sector_counts.append({"key": key, "title": sector.get("title", key), "emoji": sector.get("emoji", "📁"), "count": count})

    top_skills = {}
    for job in jobs:
        for skill in job.get("skills", "").replace(";", ",").split(","):
            skill = skill.strip().title()
            if skill and len(skill) <= 35:
                top_skills[skill] = top_skills.get(skill, 0) + 1

    subscribers = get_notification_subscribers()
    live_jobs = get_live_jobs()
    return {
        "stats": get_portal_stats(),
        "sector_counts": sorted(sector_counts, key=lambda x: x["count"], reverse=True),
        "top_skills": sorted(top_skills.items(), key=lambda x: x[1], reverse=True)[:12],
        "subscribers_count": len(subscribers),
        "live_jobs_count": len(live_jobs),
        "saved_count": len(saved_list()),
        "compare_count": len(compare_list()),
    }


def get_daily_job_spotlight():
    """Return one different portal job for each 24-hour period, cycling without
    repeating until the full portal job list has been shown."""
    from datetime import datetime, timezone
    jobs = get_all_jobs()
    if not jobs:
        return None
    # Stable ordering + 24-hour bucket = one new job every 24 hours.
    jobs = sorted(jobs, key=lambda j: (str(j.get("title", "")), str(j.get("slug", ""))))
    day_bucket = int(datetime.now(timezone.utc).timestamp() // 86400)
    job = jobs[day_bucket % len(jobs)].copy()
    title = job.get("title", "this career")
    skills = job.get("skills") or job.get("skill") or "the core skills listed in this career profile"
    degree = job.get("degree") or job.get("qualification") or "the required qualification"
    job["spotlight_text"] = (
        f"Do you know? To become a {title}, you need to ace skills such as {skills}. "
        f"Check the eligibility details and career path for the required qualification: {degree}."
    )
    job["spotlight_bucket"] = day_bucket
    return job

