@app.route("/compare")
def compare_jobs():
    jobs = get_all_jobs()
    selected = compare_list()

    slug1 = request.args.get("job1") or (selected[0] if len(selected) > 0 else None)
    slug2 = request.args.get("job2") or (selected[1] if len(selected) > 1 else None)

    job1 = next((j for j in jobs if j["slug"] == slug1), None)
    job2 = next((j for j in jobs if j["slug"] == slug2), None)

    return render_template(
        "compare.html",
        jobs=jobs,
        slug1=slug1,
        slug2=slug2,
        job1=job1,
        job2=job2,
        saved_jobs=saved_list(),
        compare_jobs_selected=selected
    )


@app.route("/eligibility", methods=["GET", "POST"])
def eligibility_checker():
    results = []
    form_data = {"degree": "", "age": "", "category": ""}

    if request.method == "POST":
        form_data["degree"] = request.form.get("degree", "")
        form_data["age"] = request.form.get("age", "")
        form_data["category"] = request.form.get("category", "")

        for job in get_all_jobs():
            if job_matches_degree(job, form_data["degree"]) and job_matches_age(job, form_data["age"]):
                results.append(job)
        results = results[:24]

    return render_template(
        "eligibility_checker.html",
        results=results,
        form_data=form_data,
        saved_jobs=saved_list(),
        compare_jobs_selected=compare_list()
    )


@app.route("/save/<job_slug>")
def toggle_saved_job(job_slug):
    saved = saved_list()
    if job_slug in saved:
        saved.remove(job_slug)
    else:
        saved.append(job_slug)
    session["saved_jobs"] = saved
    return redirect(request.referrer or url_for("jobs_index"))


@app.route("/select-compare/<job_slug>")
def toggle_compare_job(job_slug):
    selected = compare_list()
    if job_slug in selected:
        selected.remove(job_slug)
    else:
        selected.append(job_slug)
    if len(selected) > 2:
        selected = selected[-2:]
    session["compare_jobs"] = selected
    return redirect(request.referrer or url_for("jobs_index"))


@app.route("/clear-compare")
def clear_compare_jobs():
    session["compare_jobs"] = []
    return redirect(request.referrer or url_for("compare_jobs"))


