def _merge_live_jobs(primary, fallback, limit=60):
    seen = set()
    merged = []
    for job in list(primary or []) + list(fallback or []):
        sig = ((job.get("title") or "").lower().strip(), (job.get("company") or "").lower().strip(), (job.get("location") or "").lower().strip())
        if sig in seen:
            continue
        seen.add(sig)
        merged.append(job)
        if len(merged) >= limit:
            break
    return merged


def _official_board_for_job(job):
    sector = (job.get("sector_key") or "").lower()
    title = (job.get("title") or "").lower()
    apply_link = job.get("apply_link") or job.get("apply_url") or "#"
    if sector == "central" or any(x in title for x in ["ssc", "upsc", "railway", "isro", "drdo"]):
        if "isro" in title:
            return "Indian Space Research Organisation", "ISRO Careers", "https://www.isro.gov.in/Careers.html"
        if "railway" in title or "rrb" in title:
            return "Railway Recruitment Board", "RRB Official Portal", "https://www.rrbcdg.gov.in/"
        if "upsc" in title or "custom" in title:
            return "Union Public Service Commission", "UPSC Online", "https://upsconline.nic.in/"
        return "Staff Selection Commission / Central Govt", "SSC Official Portal", "https://ssc.gov.in/"
    if sector == "state":
        return "State Public Service Commission", "Official State Recruitment Portal", apply_link
    if sector in ["it", "it_sector"]:
        return "Leading IT Recruiters", "Company Careers Portal", apply_link
    if sector == "finance":
        return "Banking & Financial Institutions", "IBPS / Bank Careers Portal", "https://www.ibps.in/"
    if sector == "defence":
        return "Indian Defence Recruitment", "Official Defence Careers Portal", "https://joinindianarmy.nic.in/"
    if sector == "agriculture":
        return "Agriculture Department / ICAR", "Official Agriculture Recruitment Portal", apply_link
    if sector in ["pharma", "pharmaceuticals"]:
        return "Pharmaceutical Companies / Health Boards", "Official Pharma Careers Portal", apply_link
    if sector == "civil_aviation":
        return "Civil Aviation / Airport Authority", "Official Aviation Careers Portal", apply_link
    if sector == "marine_cruise":
        return "Maritime Board / Cruise Operators", "Official Maritime Careers Portal", apply_link
    return job.get("company_name") or job.get("organization") or "Recruiting Organisation", "Official Recruitment Portal", apply_link

def build_portal_live_jobs(keyword="", location="", experience=""):
    portal_jobs = []
    key = (keyword or "").lower()
    exp = (experience or "").lower()
    for job in get_all_jobs():
        text = " ".join([job.get("title", ""), job.get("company_name", ""), job.get("job_location", ""), job.get("skills", ""), job.get("degree", ""), job.get("sector_key", ""), job.get("experience", "")]).lower()
        if key and key not in text:
            continue
        if exp and exp not in text and exp not in ["experienced", "remote"]:
            continue
        item = {
            "source": "Portal Career Role",
            "badge": "PORTAL",
            "remote_flag": False,
            "title": job.get("title", "Untitled Job"),
            "company": job.get("company_name") or job.get("organization") or "Multiple recruiters",
            "location": job.get("job_location") or "As per notification",
            "salary": (job.get("pay", {}).get("A", {}) if isinstance(job.get("pay"), dict) else {}).get("annual", "As per notification"),
            "experience": job.get("experience") or "Fresher / Experienced",
            "qualification": job.get("degree") or "Check eligibility details",
            "skills": job.get("skills") or "Check job details",
            "posted_at": job.get("apply_dates") or "Career guidance role",
            "apply_url": job.get("apply_link") or "#",
            "primary_organization": _official_board_for_job(job)[0],
            "official_board": _official_board_for_job(job)[1],
            "official_portal": _official_board_for_job(job)[2],
            "roadmap": job.get("roadmap") or job.get("career_growth") or "Build skills → Apply → Interview → Selection → Growth",
            "portal_slug": job.get("slug", ""),
            "sector_key": job.get("sector_key", ""),
            "department_key": job.get("department_key", "")
        }
        if _location_matches(item, location):
            portal_jobs.append(item)
    return portal_jobs[:30]


@app.route("/live-jobs")
def live_jobs():
    keyword = request.args.get("q", "").strip()
    location = request.args.get("location", "").strip()
    experience = request.args.get("experience", "").strip()
    tab = request.args.get("tab", "all").strip().lower()

    # Clean common typing mistakes and avoid comma-list confusion.
    location = _norm_location_text(location).title() if location else ""
    if "," in location and tab == "all":
        location = location.split(",")[0].strip()

    remote_only = request.args.get("remote", "").strip() == "1" or experience.lower() == "remote" or tab in ["remote", "worldwide", "fresher_remote", "remote_intern", "python_remote"]

    if tab == "india" and not location:
        location = "India"
    if tab == "worldwide":
        location = "Worldwide"
    if tab == "fresher_remote":
        keyword = keyword or "fresher"
        experience = "fresher"
    if tab == "remote_intern":
        keyword = keyword or "intern"
        experience = "intern"
    if tab == "python_remote":
        keyword = keyword or "python"

    portal_jobs = build_portal_live_jobs(keyword, location, experience)
    saved_api_jobs = [dict(row) for row in get_live_jobs(keyword)]

    # City searches use India API only; remote API is used only for remote tabs.
    if remote_only:
        external_jobs = fetch_remotive_jobs(keyword or "software", location if location in ["India", "Worldwide", "Remote"] else "Remote", limit=36)
    else:
        external_jobs = fetch_adzuna_jobs(keyword or "software", location or "India", limit=28)
        # Free APIs may return only 1-2 India jobs. Add a curated India feed so
        # the India tab always looks useful while still showing real API results first.
        if not location or location.lower() in ["india", "in", "guntur", "hyderabad", "bengaluru", "bangalore", "chennai", "pune", "mumbai", "noida", "gurugram", "vijayawada", "visakhapatnam"]:
            external_jobs = _merge_live_jobs(external_jobs, curated_india_live_jobs(keyword, location or "India", limit=60), limit=60)

    if experience and not remote_only:
        exp = experience.lower()
        external_jobs = [j for j in external_jobs if exp in (j.get("experience", "") + " " + j.get("badge", "") + " " + j.get("location", "") + " " + j.get("title", "")).lower() or exp == "experienced"]

    def looks_remote(job):
        text = " ".join([str(job.get(k, "")) for k in ["badge", "location", "title", "skills", "source"]]).lower()
        return "remote" in text or "worldwide" in text or "anywhere" in text or "global" in text or "wfh" in text

    if remote_only:
        external_jobs = [j for j in external_jobs if looks_remote(j)]
        portal_jobs = [j for j in portal_jobs if looks_remote(j)]
        saved_api_jobs = [j for j in saved_api_jobs if looks_remote(j)]
    elif location:
        external_jobs = [j for j in external_jobs if _location_matches(j, location)]
        portal_jobs = [j for j in portal_jobs if _location_matches(j, location)]
        saved_api_jobs = [j for j in saved_api_jobs if _location_matches(j, location)]

    for job in external_jobs:
        if looks_remote(job):
            job["remote_flag"] = True
            job["badge"] = "REMOTE"

    jobs = external_jobs + portal_jobs + saved_api_jobs

    # Add display-only fields so the template does not duplicate badges or show odd single letters.
    for index, job in enumerate(jobs):
        is_remote = looks_remote(job)
        job["remote_flag"] = bool(is_remote or job.get("remote_flag"))
        job["display_badge"] = "REMOTE" if job["remote_flag"] else ("PORTAL" if job.get("portal_slug") else "LIVE")
        job["company_initials"] = _company_initials(job.get("company"))
        if "salary" in job:
            job["salary"] = _clean_live_salary(job.get("salary"))
        job.setdefault("primary_organization", job.get("company") or "Recruiting Organisation")
        job.setdefault("official_board", "Official Recruitment Portal")
        job.setdefault("official_portal", job.get("apply_url") or "#")
        job.setdefault("roadmap", "Prepare skills → Apply → Interview → Selection → Career growth")
        # Simple AI match score for presentation. It is deterministic and based on query/category/remote match.
        score = 74 + ((index * 7) % 18)
        if keyword and keyword.lower() in (job.get("title", "") + " " + job.get("skills", "")).lower():
            score += 5
        if remote_only and job["remote_flag"]:
            score += 4
        job["ai_match"] = min(score, 98)

    remote_count = sum(1 for j in jobs if j.get("remote_flag"))

    return render_template(
        "live_jobs.html",
        jobs=jobs,
        keyword=keyword,
        location_filter=location,
        experience_filter=experience,
        remote_only=remote_only,
        active_tab=tab,
        remote_count=remote_count,
        total_live=len(external_jobs) + len(saved_api_jobs),
        total_portal=len(portal_jobs),
        api_status="connected" if external_jobs else "fallback"
    )


@app.route("/api/live-jobs")
def api_live_jobs():
    keyword = request.args.get("q", "").strip()
    location = request.args.get("location", "").strip()
    jobs = []
    if app.config.get("REMOTE", True):
        if location.lower() in ["remote", "worldwide", "global"]:
            jobs = fetch_remotive_jobs(keyword or "software", location or "Remote", limit=24)
        else:
            jobs = fetch_adzuna_jobs(keyword or "software", location or "India", limit=24)
            jobs = _merge_live_jobs(jobs, curated_india_live_jobs(keyword, location or "India", limit=40), limit=40)
    if not jobs:
        jobs = build_portal_live_jobs(keyword, location, "")
    for i, job in enumerate(jobs):
        job.setdefault("company_initials", _company_initials(job.get("company")))
        job.setdefault("display_badge", "REMOTE" if job.get("remote_flag") else "LIVE")
        job.setdefault("ai_match", min(82 + ((i * 5) % 15), 98))
        job.setdefault("primary_organization", job.get("company") or "Recruiting Organisation")
        job.setdefault("official_board", "Official Recruitment Portal")
        job.setdefault("official_portal", job.get("apply_url") or "#")
        job.setdefault("roadmap", "Prepare skills → Apply → Interview → Selection → Career growth")
    return {"jobs": jobs, "count": len(jobs)}

