@app.route("/admin/login", methods=["GET", "POST"])
def admin_login():
    if session.get("admin_logged_in"):
        return redirect(url_for("admin_dashboard"))

    if request.method == "POST":
        username = request.form.get("username", "")
        password = request.form.get("password", "")
        if username == "admin" and password == "admin123":
            session["admin_logged_in"] = True
            return redirect(url_for("admin_dashboard"))
        return render_template("admin_login.html", error="Invalid username or password")

    return render_template("admin_login.html")


@app.route("/admin", methods=["GET", "POST"])
@app.route("/admin/sectors", methods=["GET", "POST"])
def admin_dashboard():
    guard = require_admin()
    if guard:
        return guard

    message = None
    if request.method == "POST":
        key = request.form.get("key", "").strip().lower().replace(" ", "_")
        title = request.form.get("title", "").strip()
        emoji = request.form.get("emoji", "📁").strip() or "📁"
        if key and title:
            conn = get_db()
            conn.execute(
                "INSERT OR REPLACE INTO sectors(key, title, emoji) VALUES (?, ?, ?)",
                (key, title, emoji)
            )
            conn.commit()
            conn.close()
            message = "Sector saved successfully in SQLite database."
        else:
            message = "Please enter sector key and title."

    return render_template("admin_sectors.html", sectors=build_admin_sector_rows(), message=message)


