@app.route("/admin/jobs/edit/<job_slug>", methods=["GET", "POST"])
def admin_edit_job(job_slug):
    guard = require_admin()
    if guard:
        return guard
    job = get_job_by_slug(job_slug)
    if not job:
        abort(404)
    message = None
    if request.method == "POST":
        sector_key, department_key, new_job = build_job_from_form()
        if not new_job.get("slug"):
            new_job["slug"] = job_slug
        conn = get_db()
        if new_job["slug"] != job_slug:
            conn.execute("DELETE FROM jobs WHERE slug = ?", (job_slug,))
        insert_job(conn.cursor(), sector_key, department_key, new_job)
        conn.commit()
        conn.close()
        message = "Job updated successfully in SQLite database."
        job = get_job_by_slug(new_job["slug"])
    return render_template(
        "admin_job_form.html",
        job=job,
        sectors=build_admin_sector_rows(),
        departments=build_admin_department_rows(),
        message=message
    )


