# Run the app
# -------------------------

def refresh_live_job_cache():
    """Background refresh hook. Fetches live jobs when API keys/network are available."""
    if not app.config.get("REMOTE", True):
        return
    try:
        jobs = fetch_adzuna_jobs("software", "India", limit=10) or fetch_remotive_jobs("software", "Remote", limit=10)
        if not jobs:
            return
        conn = get_db()
        cur = conn.cursor()
        for job in jobs[:20]:
            cur.execute(
                """
                INSERT INTO live_job_posts(title, company, location, source, apply_url, skills, posted_at)
                VALUES (?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    job.get("title"),
                    job.get("company"),
                    job.get("location"),
                    job.get("source"),
                    job.get("apply_url"),
                    job.get("skills"),
                    job.get("posted_at"),
                ),
            )
        conn.commit()
        conn.close()
    except Exception:
        pass


try:
    from apscheduler.schedulers.background import BackgroundScheduler
    scheduler = BackgroundScheduler(daemon=True)
    scheduler.add_job(
        refresh_live_job_cache,
        "interval",
        minutes=30,
        id="live_job_refresh",
        replace_existing=True,
    )
    scheduler.start()
except Exception:
    scheduler = None


init_db()

